function parseChatOptions(args: string[]): ChatCommandOptions {
	const opts: ChatCommandOptions = {
		model: "gpt-4o",
		apiKey: undefined,
		baseUrl: undefined,
	};

	let i = 0;
	while (i < args.length) {
		const arg = args[i];
		if (!arg) {
			i += 1;
			continue;
		}
		switch (arg) {
			case "--model":
				opts.model = args[i + 1] ?? opts.model;
				i += 2;
				break;
			case "--api-key":
				opts.apiKey = args[i + 1];
				i += 2;
				break;
			case "--url":
				opts.baseUrl = args[i + 1];
				i += 2;
				break;
			case "--help":
			case "-h":
				usage();
				process.exit(0);
				break;
			default:
				console.warn(`[Talox CLI] Unknown chat option: ${arg}`);
				i += 1;
				break;
		}
	}

	return opts;
}

