async function runDaemon(args: string[]): Promise<void> {
	const opts = parseDaemonOptions(args);
	const config: import("../core/daemon/TaloxDaemon.js").DaemonConfig = {};
	if (opts.socketPath !== undefined) {
		config.socketPath = opts.socketPath;
	}
	if (opts.port !== undefined) {
		config.port = opts.port;
	}

	const daemon = new TaloxDaemon(config);
	await daemon.start();

	const address = daemon.getAddress();
	const isTcp = os.platform() === "win32" || opts.port !== undefined;
	if (isTcp) {
		console.log(`[Talox Daemon] Listening on TCP ${address} (PID ${process.pid})`);
	} else {
		const socketPath = opts.socketPath ?? "/tmp/talox-daemon.sock";
		console.log(`[Talox Daemon] Listening on socket ${socketPath} (PID ${process.pid})`);
	}

	const gracefulShutdown = async () => {
		console.log("[Talox Daemon] Shutting down...");
		await daemon.stop();
		process.exit(0);
	};
	process.on("SIGINT", gracefulShutdown);
	process.on("SIGTERM", gracefulShutdown);
}

export async function runDoctor(options?: { fix?: boolean }): Promise<DoctorResult> {
	const fix = options?.fix ?? false;
	let chromiumExecutable = await resolveChromiumExecutable();
	let browserCheck = checkBrowserBinaries(chromiumExecutable);

	if (fix && browserCheck.status === "error") {
		await installChromium();
		chromiumExecutable = await resolveChromiumExecutable();
		browserCheck = checkBrowserBinaries(chromiumExecutable);
	}

	// These probes are independent once any requested browser installation is
	// complete. Run them concurrently so a slow network check cannot serially
	// consume the same wall-clock budget as a slow browser launch.
	const [
		nodeCheck,
		playwrightCheck,
		profileCheck,
		tempCheck,
		networkCheck,
		displayCheck,
		dependenciesCheck,
		configCheck,
		liveLaunchCheck,
	] = await Promise.all([
		checkNodeVersion(),
		checkPlaywrightInstalled(),
		checkProfileDirectory(fix),
		checkTempDirectory(),
		checkNetworkConnectivity(),
		checkDisplayServer(),
		checkDependencies(),
		checkConfigFile(fix),
		checkLiveLaunch(chromiumExecutable),
	]);

	const checks: DoctorCheck[] = [
		nodeCheck,
		playwrightCheck,
		browserCheck,
		profileCheck,
		tempCheck,
		networkCheck,
		displayCheck,
		dependenciesCheck,
		configCheck,
		liveLaunchCheck,
	];

	const passed = checks.filter((c) => c.status === "ok").length;
	const warnings = checks.filter((c) => c.status === "warning").length;
	const errors = checks.filter((c) => c.status === "error").length;

	return {
		checks,
		passed,
		warnings,
		errors,
		timestamp: new Date().toISOString(),
	};
}

async function runDoctorCommand(args: string[]): Promise<void> {
	if (args.includes("--help") || args.includes("-h")) {
		usage();
		process.exit(0);
	}
	const fix = args.includes("--fix");
	const version = await readTaloxVersion();
	const result = await runDoctor({ fix });
	console.log(formatDoctorOutput(result, version));
	if (result.errors > 0) {
		process.exit(1);
	}
}

