export function parseMultiAgentRunOptions(args: string[]): MultiAgentRunOptions {
	const opts: MultiAgentRunOptions = {
		goal: "",
		model: "gpt-4o",
		maxIterations: 10,
		strategy: "balanced",
		agents: 1,
	};
	const positional: string[] = [];

	let i = 0;
	while (i < args.length) {
		const arg = args[i];
		if (!arg) {
			i += 1;
			continue;
		}

		if (arg.startsWith("--agents=")) {
			opts.agents = parsePositiveInteger(arg.slice("--agents=".length), opts.agents);
			i += 1;
			continue;
		}

		switch (arg) {
			case "--url": {
				const value = args[i + 1];
				if (value !== undefined) opts.url = value;
				i += 2;
				break;
			}
			case "--model":
				opts.model = args[i + 1] ?? opts.model;
				i += 2;
				break;
			case "--api-key": {
				const value = args[i + 1];
				if (value !== undefined) opts.apiKey = value;
				i += 2;
				break;
			}
			case "--base-url": {
				const value = args[i + 1];
				if (value !== undefined) opts.baseUrl = value;
				i += 2;
				break;
			}
			case "--max-iterations":
				opts.maxIterations = parsePositiveInteger(args[i + 1], opts.maxIterations);
				i += 2;
				break;
			case "--strategy": {
				const raw = args[i + 1] as LoopStrategy | undefined;
				if (raw && VALID_STRATEGIES.has(raw)) opts.strategy = raw;
				i += 2;
				break;
			}
			case "--skills-dir": {
				const value = args[i + 1];
				if (value !== undefined) opts.skillsDir = value;
				i += 2;
				break;
			}
			case "--agents":
				opts.agents = parsePositiveInteger(args[i + 1], opts.agents);
				i += 2;
				break;
			default:
				if (!arg.startsWith("-")) positional.push(arg);
				i += 1;
				break;
		}
	}

	opts.goal = positional.join(" ").trim();
	return opts;
}

function parseRunOptions(args: string[]): RunCommandOptions {
	const VALID_STRATEGIES = new Set<string>(["conservative", "balanced", "aggressive"]);
	const opts: RunCommandOptions = {
		goal: "",
		url: undefined,
		model: "gpt-4o",
		apiKey: undefined,
		baseUrl: undefined,
		maxIterations: 10,
		strategy: "balanced",
		skillsDir: undefined,
		agents: 1,
	};

	let i = 0;
	while (i < args.length) {
		const arg = args[i];
		if (!arg) {
			i += 1;
			continue;
		}
		switch (arg) {
			case "--url":
				opts.url = args[i + 1];
				i += 2;
				break;
			case "--model":
				opts.model = args[i + 1] ?? opts.model;
				i += 2;
				break;
			case "--api-key":
				opts.apiKey = args[i + 1];
				i += 2;
				break;
			case "--base-url":
				opts.baseUrl = args[i + 1];
				i += 2;
				break;
			case "--max-iterations":
				opts.maxIterations = Number(args[i + 1]) || opts.maxIterations;
				i += 2;
				break;
			case "--strategy": {
				const raw = args[i + 1] ?? "balanced";
				opts.strategy = VALID_STRATEGIES.has(raw) ? (raw as RunCommandOptions["strategy"]) : opts.strategy;
				i += 2;
				break;
			}
			case "--skills-dir":
				opts.skillsDir = args[i + 1];
				i += 2;
				break;
			case "--agents":
				opts.agents = Number(args[i + 1]) || 1;
				i += 2;
				break;
			case "--help":
			case "-h":
				usage();
				process.exit(0);
				break;
			default:
				if (!arg.startsWith("-")) {
					opts.goal = arg;
				} else {
					console.warn(`[Talox CLI] Unknown run option: ${arg}`);
				}
				i += 1;
				break;
		}
	}

	return opts;
}

