export async function runMultiAgentRun(args: string[]): Promise<void> {
	const opts = parseMultiAgentRunOptions(args);
	if (!opts.goal) {
		console.error('[Talox CLI] Error: No goal provided. Usage: talox run "<goal>" --agents <N> [options]');
		process.exitCode = 1;
		return;
	}
	if (opts.agents < 2) {
		throw new Error("Multi-agent run requires at least 2 agents");
	}

	const apiKey = opts.apiKey ?? process.env["OPENAI_API_KEY"];
	if (!apiKey) {
		console.error("[Talox CLI] Error: Multi-agent run requires an API key. Use --api-key or set OPENAI_API_KEY.");
		process.exitCode = 1;
		return;
	}

	console.log(`[Talox Run] Starting coordinated run with ${opts.agents} agents: "${opts.goal}"`);

	const coordinator = new AgentCoordinator({
		agents: opts.agents,
		baseDir: path.join(process.cwd(), ".talox", "profiles", "run"),
		settings: {
			headed: false,
			verbosity: 1,
		} as TaloxSettings,
	});

	const planner: PlannerConfig = {
		model: opts.model,
		apiKey,
	};
	const apiBaseUrl = opts.baseUrl ?? process.env["OPENAI_BASE_URL"];
	if (apiBaseUrl) planner.apiBaseUrl = apiBaseUrl;

	const goal: TaskGoal = {
		description: opts.goal,
		maxIterations: opts.maxIterations,
		strategy: opts.strategy,
	};
	if (opts.url) goal.startUrl = opts.url;

	let interrupting = false;
	const interrupt = () => {
		if (interrupting) return;
		interrupting = true;
		console.log("[Talox Run] Interrupt received — stopping agents...");
		void coordinator
			.stop()
			.catch((error: unknown) => {
				console.error(`[Talox Run] Shutdown error: ${error instanceof Error ? error.message : String(error)}`);
			})
			.finally(() => process.exit(130));
	};
	process.on("SIGINT", interrupt);

	try {
		await coordinator.launch({ profileClass: "ops", headed: false });

		const loopOptions: PlanDelegateObserveOptions = {
			goal,
			planner,
			maxWaves: opts.maxIterations,
			onProgress(wave) {
				const successful = wave.result.results.filter((result) => result.success).length;
				console.log(
					`[ wave ${wave.wave} ] ${successful}/${wave.tasks.length} tasks succeeded · ${wave.result.conflicts.length} conflicts`,
				);
			},
		};
		if (opts.skillsDir) loopOptions.skillsDir = opts.skillsDir;

		const loop = new PlanDelegateObserveLoop(coordinator, loopOptions);
		const result = await loop.run();
		console.log("");
		console.log(`[Talox CLI] Multi-agent run completed: ${result.status}`);
		console.log(`[Talox CLI] Stop reason: ${result.stopReason}`);
		console.log(`[Talox CLI] Waves: ${result.totalWaves}`);
		console.log(`[Talox CLI] Duration: ${(result.totalDurationMs / 1000).toFixed(1)}s`);
		const sharedKeys = Object.keys(result.sharedState);
		console.log(`[Talox CLI] Shared state keys: ${sharedKeys.join(", ") || "none"}`);
		if (result.status === "failed") process.exitCode = 1;
	} finally {
		process.off("SIGINT", interrupt);
		if (!interrupting) await coordinator.stop();
	}
}

async function runRun(args: string[]): Promise<void> {
	const opts = parseRunOptions(args);

	if (!opts.goal) {
		console.error('[Talox CLI] Error: No goal provided. Usage: talox run "<goal>" [options]');
		process.exit(1);
	}

	const apiKey = opts.apiKey ?? process.env["OPENAI_API_KEY"];
	if (!apiKey) {
		console.error("[Talox CLI] Error: No API key provided. Use --api-key or set OPENAI_API_KEY env var.");
		process.exit(1);
	}

	console.log(`[Talox Run] Starting autonomous loop: "${opts.goal}"`);

	const talox = new TaloxController(process.cwd(), {
		settings: {
			headed: false,
			verbosity: 1,
		},
	});

	let totalCost = 0; // NOSONAR — mutated inside onProgress closure

	const loopOptions: import("../core/loop/types.js").AutonomousLoopOptions = {
		goal: {
			description: opts.goal,
			maxIterations: opts.maxIterations,
			strategy: opts.strategy,
		},
		planner: {
			model: opts.model,
			apiKey,
		},
		onProgress(iteration) {
			if (iteration.tokenUsage) {
				totalCost += iteration.tokenUsage.estimatedCostUsd;
			}
			const firstStep = iteration.plan.steps[0];
			if (iteration.plan.goalAchieved) {
				console.log(
					`[ iteration ${iteration.iteration} ] goal achieved \u2713 (${iteration.iteration} iterations, $${totalCost.toFixed(3)})`,
				);
			} else if (firstStep) {
				console.log(`[ iteration ${iteration.iteration} ] observing \u2192 planning \u2192 ${firstStep.action}`);
			} else {
				console.log(`[ iteration ${iteration.iteration} ] observing \u2192 planning \u2192 ${iteration.result.status}`);
			}
		},
	};

	if (opts.url !== undefined) {
		loopOptions.goal.startUrl = opts.url;
	}
	if (opts.baseUrl !== undefined) {
		loopOptions.planner.apiBaseUrl = opts.baseUrl;
	}
	if (opts.skillsDir !== undefined) {
		loopOptions.skillsDir = opts.skillsDir;
	}

	const interrupt = async () => {
		console.log("[Talox Run] Interrupt received — stopping...");
		process.exit(0);
	};
	process.on("SIGINT", interrupt);

	try {
		await talox.launch("run", "ops", "chromium");

		const loop = new AutonomousLoop(talox, loopOptions);
		const result = await loop.run();

		console.log("");
		console.log(`[Talox CLI] Run completed: ${result.status}`);
		console.log(`[Talox CLI] Stop reason: ${result.stopReason}`);
		console.log(`[Talox CLI] Iterations: ${result.totalIterations}`);
		console.log(`[Talox CLI] Duration: ${(result.totalDurationMs / 1000).toFixed(1)}s`);
		console.log(`[Talox CLI] Cost: $${result.totalCostUsd.toFixed(3)}`);
		if (result.createdSkills.length > 0) {
			console.log(`[Talox CLI] Skills created: ${result.createdSkills.join(", ")}`);
		}

		loop.dispose();
	} finally {
		process.off("SIGINT", interrupt);
		await talox.stop();
	}
}

