	timestamp: string;
	console: {
		errors: string[];
		warnings?: string[];
		logs?: string[];
	};
	network: {
		failedRequests: Array<{ url: string; status: number; type?: string }>;
		exceptions?: any[];
	};
	/** Flat ordered list of all AX tree nodes with bounding boxes. */
	nodes: TaloxNode[];
	interactiveElements: Array<{
		/** CSS selector usable with click()/type(). Derived from id, name, aria-label, or nth-of-type. */
		id: string;
		tagName: string;
		role?: string;
		/** Label text from <label>, aria-label, placeholder, or textContent. */
		text?: string;
		boundingBox: { x: number; y: number; width: number; height: number };
		isActionable?: boolean;
		/** True when this element was discovered via cursor/onclick/tabindex heuristics outside the AX tree. */
		cursorDetected?: boolean;
		/** How the element was detected when cursorDetected is true. */
		detectionMethod?: CursorDetectionMethod;
		/** Content trust: "first-party" (same origin) or "external" (cross-origin, iframe, unknown). */
		trust?: "first-party" | "external";
	}>;
	bugs: TaloxBug[];

	// ── v1 optional fields (non-breaking additions) ───────────────────────────
	/** Full AX-Tree root node (present when perceptionDepth: 'full'). */
	axTree?: TaloxNode;
	/** Timing metadata for this collection cycle. */
	timing?: TaloxStateTiming;
	/**
	 * State diff relative to the previous action's state.
	 * Populated by ActionExecutor when a prior state is available.
	 */
	diff?: TaloxStateDiff;
	/** Profile ID that produced this state (set by SessionManager). */
	profileId?: string;
	/**
	 * Domain-specific hints injected from matching skills.
	 * Populated by TaloxController.navigate() when skills match the current hostname.
	 */
	domainHints?: string[];
	/** Visual artifact references produced during this action cycle. */
	screenshots?: {
		fullPage?: string;
		crops?: Array<{ id: string; path: string; reason: string }>;
	};
	/**
	 * Set when this state is NOT a reading of a page, but a report that the
	 * reading could not be taken. Absent on every real state.
	 *
	 * A failed navigation used to be returned as `{ url: "", title: "Error" }`
	 * and nothing else, which no caller could tell apart from a real page whose
	 * title happens to be "Error". `talox screenshot <url>` therefore captured
	 * `about:blank`, wrote the file, printed "Annotated screenshot saved" and
	 * exited 0 — the same blank 5,837-byte PNG for every URL on earth.
	 *
	 * Callers must branch on this field, never on `title` or on an empty `url`.
	 */
	failed?: {
		/** What went wrong, in the words the thrower used. */
		reason: string;
		/** The operation that could not be completed, e.g. "navigate". */
		operation: string;
	};
